1	<?php
2	
3	namespace App\Filament\Widgets;
4	
5	use App\Models\Activity;
6	use Filament\Support\RawJs;
7	use Filament\Widgets\ChartWidget;
8	use Filament\Widgets\Concerns\InteractsWithPageFilters;
9	use Illuminate\Database\Eloquent\Builder;
10	
11	/**
12	 * Ripartizione percentuale delle attività per tipo,
13	 * filtrata per il periodo selezionato in dashboard.
14	 */
15	class ActivityTypesChartWidget extends ChartWidget
16	{
17	    use InteractsWithPageFilters;
18	
19	    protected static ?string $heading = 'Tipi di attività';
20	
21	    protected static ?int $sort = 0;
22	
23	    protected static ?string $maxHeight = '320px';
24	
25	    /**
26	     * Palette categorica: slot assegnati in ordine fisso, mai ciclati.
27	     * L'ottavo slot è riservato alla fetta "Altro".
28	     */
29	    private const COLORS = [
30	        '#2a78d6', // blue
31	        '#eb6834', // orange
32	        '#1baf7a', // aqua
33	        '#eda100', // yellow
34	        '#e87ba4', // magenta
35	        '#008300', // green
36	        '#4a3aa7', // violet
37	    ];
38	
39	    private const OTHER_COLOR = '#e34948'; // red
40	
41	    protected function getType(): string
42	    {
43	        return 'pie';
44	    }
45	
46	    protected function getData(): array
47	    {
48	        $counts = $this->getTypeCounts();
49	
50	        if ($counts->isEmpty()) {
51	            return [
52	                'datasets' => [['data' => []]],
53	                'labels' => [],
54	            ];
55	        }
56	
57	        $colors = array_slice(self::COLORS, 0, $counts->count());
58	
59	        // se ho ripiegato le code in "Altro" l'ultima fetta prende il colore riservato
60	        if ($counts->keys()->last() === 'Altro') {
61	            $colors[count($colors) - 1] = self::OTHER_COLOR;
62	        }
63	
64	        return [
65	            'datasets' => [
66	                [
67	                    'label' => 'Attività',
68	                    'data' => $counts->values()->all(),
69	                    'backgroundColor' => $colors,
70	                    // bordo trasparente = 2px di superficie fra le fette, in entrambi i temi
71	                    'borderColor' => 'transparent',
72	                    'borderWidth' => 2,
73	                ],
74	            ],
75	            'labels' => $counts->keys()->all(),
76	        ];
77	    }
78	
79	    protected function getOptions(): RawJs
80	    {
81	        return RawJs::make(<<<'JS'
82	            {
83	                plugins: {
84	                    legend: {
85	                        position: 'right',
86	                        labels: {
87	                            boxWidth: 12,
88	                            boxHeight: 12,
89	                            usePointStyle: true,
90	                            pointStyle: 'circle',
91	                        },
92	                    },
93	                    tooltip: {
94	                        callbacks: {
95	                            label: (context) => {
96	                                const total = context.dataset.data.reduce((sum, value) => sum + value, 0);
97	                                const percentage = total ? (context.parsed / total * 100) : 0;
98	
99	                                return ` ${context.label}: ${context.parsed} (${percentage.toFixed(1)}%)`;
100	                            },
101	                        },
102	                    },
103	                },
104	            }
105	        JS);
106	    }
107	
108	    /**
109	     * Conteggio attività per tipo, decrescente.
110	     * Oltre le 7 fette più grandi il resto viene accorpato in "Altro".
111	     */
112	    private function getTypeCounts(): \Illuminate\Support\Collection
113	    {
114	        $counts = Activity::query()
115	            ->where('user_id', auth()->id())
116	            ->when(
117	                $this->filters['startDate'] ?? null,
118	                fn (Builder $query, $date) => $query->whereDate('start_date_local', '>=', $date)
119	            )
120	            ->when(
121	                $this->filters['endDate'] ?? null,
122	                fn (Builder $query, $date) => $query->whereDate('start_date_local', '<=', $date)
123	            )
124	            ->selectRaw('COALESCE(type, ?) as type, COUNT(*) as total', ['Sconosciuto'])
125	            ->groupBy('type')
126	            ->pluck('total', 'type')
127	            ->sortDesc();
128	
129	        $maxSlices = count(self::COLORS);
130	
131	        if ($counts->count() <= $maxSlices) {
132	            return $counts;
133	        }
134	
135	        return $counts
136	            ->take($maxSlices - 1)
137	            ->put('Altro', $counts->slice($maxSlices - 1)->sum());
138	    }
139	}
140

