3	namespace App\Filament\Pages;
4	
5	use App\Models\Activity;
6	use Filament\Forms\Components\DatePicker;
7	use Filament\Forms\Form;
8	use Filament\Pages\Dashboard as BaseDashboard;
9	use Filament\Pages\Dashboard\Concerns\HasFiltersForm;
10	
11	/**
12	 * Dashboard con filtro per periodo, condiviso da tutti i widget.
13	 */
14	class Dashboard extends BaseDashboard
15	{
16	    use HasFiltersForm;
17	
18	    /**
19	     * Filament applica il default di un campo solo al primissimo fill "da zero":
20	     * se la sessione contiene già un filtro esplicito (anche vuoto, salvato prima
21	     * che questi default esistessero), il default non scatta più. Qui forziamo
22	     * i valori pre-calcolati ogni volta che entrambi i campi risultano vuoti.
23	     */
24	    public function mount(): void
25	    {
26	        if (filled($this->filters['startDate'] ?? null) || filled($this->filters['endDate'] ?? null)) {
27	            return;
28	        }
29	
30	        $range = $this->getUserActivitiesDateRange();
31	
32	        $this->filters['startDate'] = $range->min;
33	        $this->filters['endDate'] = $range->max;
34	
35	        $this->getFiltersForm()->fill($this->filters);
36	
37	        if ($this->persistsFiltersInSession()) {
38	            session()->put($this->getFiltersSessionKey(), $this->filters);
39	        }
40	    }
41	
42	    public function filtersForm(Form $form): Form
43	    {
44	        return $form
45	            ->schema([
46	                DatePicker::make('startDate')
47	                    ->label('Data inizio')
48	                    ->default(fn () => $this->getUserActivitiesDateRange()->min)
49	                    ->maxDate(fn (callable $get) => $get('endDate') ?: now()),
50	
51	                DatePicker::make('endDate')
52	                    ->label('Data fine')
53	                    ->default(fn () => $this->getUserActivitiesDateRange()->max)
54	                    ->minDate(fn (callable $get) => $get('startDate'))
55	                    ->maxDate(now()),
56	            ])
57	            ->columns(2);
58	    }
59	
60	    /**
61	     * Data della prima e dell'ultima attività registrata dall'utente,
62	     * usate come estremi preimpostati del filtro periodo.
63	     */
64	    protected function getUserActivitiesDateRange(): object
65	    {
66	        return once(fn () => Activity::query()
67	            ->where('user_id', auth()->id())
68	            ->selectRaw('min(start_date_local) as min, max(start_date_local) as max')
69	            ->first());
70	    }
71	}
