3	namespace App\Filament\Widgets;
4	
5	use App\Enums\ActivityType;
6	use App\Models\Activity;
7	use Filament\Support\Colors\Color;
8	use Filament\Support\RawJs;
9	use Filament\Widgets\ChartWidget;
10	use Filament\Widgets\Concerns\InteractsWithPageFilters;
11	use Illuminate\Database\Eloquent\Builder;
12	use Illuminate\Support\Collection;
13	
14	/**
15	 * Ripartizione percentuale delle attività per tipo,
16	 * filtrata per il periodo selezionato in dashboard.
17	 *
18	 * Colori ed etichette arrivano da ActivityType, la stessa fonte
19	 * usata dal badge "Tipo" nella tabella attività, per restare coerenti
20	 * in tutto il pannello.
21	 */
22	class ActivityTypesChartWidget extends ChartWidget
23	{
24	    use InteractsWithPageFilters;
25	
26	    protected static ?string $heading = 'Tipi di attività';
27	
28	    protected static ?int $sort = 0;
29	
30	    protected static ?string $maxHeight = '320px';
31	
32	    /**
33	     * Oltre le fette più grandi il resto viene accorpato in "Altro",
34	     * altrimenti una torta con troppe fette diventa illeggibile.
35	     */
36	    private const MAX_SLICES = 7;
37	
38	    protected function getType(): string
39	    {
40	        return 'pie';
41	    }
42	
43	    protected function getData(): array
44	    {
45	        $slices = $this->getSlices();
46	
47	        if ($slices->isEmpty()) {
48	            return [
49	                'datasets' => [['data' => []]],
50	                'labels' => [],
51	            ];
52	        }
53	
54	        return [
55	            'datasets' => [
56	                [
57	                    'label' => 'Attività',
58	                    'data' => $slices->pluck('total')->all(),
59	                    'backgroundColor' => $slices->pluck('color')->all(),
60	                    // bordo trasparente = 2px di superficie fra le fette, in entrambi i temi
61	                    'borderColor' => 'transparent',
62	                    'borderWidth' => 2,
63	                ],
64	            ],
65	            'labels' => $slices->pluck('label')->all(),
66	        ];
67	    }
68	
69	    protected function getOptions(): RawJs
70	    {
71	        return RawJs::make(<<<'JS'
72	            {
73	                plugins: {
74	                    legend: {
75	                        position: 'right',
76	                        labels: {
77	                            boxWidth: 12,
78	                            boxHeight: 12,
79	                            usePointStyle: true,
80	                            pointStyle: 'circle',
81	                        },
82	                    },
83	                    tooltip: {
84	                        callbacks: {
85	                            label: (context) => {
86	                                const total = context.dataset.data.reduce((sum, value) => sum + value, 0);
87	                                const percentage = total ? (context.parsed / total * 100) : 0;
88	
89	                                return ` ${context.label}: ${context.parsed} (${percentage.toFixed(1)}%)`;
90	                            },
91	                        },
92	                    },
93	                },
94	            }
95	        JS);
96	    }
97	
98	    /**
99	     * Una riga per fetta: totale, etichetta e colore risolti da ActivityType.
100	     * Oltre MAX_SLICES le code vengono accorpate in "Altro".
101	     *
102	     * @return Collection<int, array{total: int, label: string, color: string}>
103	     */
104	    private function getSlices(): Collection
105	    {
106	        $counts = Activity::query()
107	            ->where('user_id', auth()->id())
108	            ->when(
109	                $this->filters['startDate'] ?? null,
110	                fn (Builder $query, $date) => $query->whereDate('start_date_local', '>=', $date)
111	            )
112	            ->when(
113	                $this->filters['endDate'] ?? null,
114	                fn (Builder $query, $date) => $query->whereDate('start_date_local', '<=', $date)
115	            )
116	            ->selectRaw('type, COUNT(*) as total')
117	            ->groupBy('type')
118	            ->pluck('total', 'type')
119	            ->sortDesc();
120	
121	        $slices = $counts->map(function (int $total, ?string $type) {
122	            $activityType = $type !== null ? ActivityType::tryFrom($type) : null;
123	
124	            return [
125	                'total' => $total,
126	                'label' => $activityType?->getLabel() ?? 'Sconosciuto',
127	                'color' => $this->colorToRgb($activityType?->getColor() ?? Color::Gray),
128	            ];
129	        })->values();
130	
131	        if ($slices->count() <= self::MAX_SLICES) {
132	            return $slices;
133	        }
134	
135	        return $slices
136	            ->take(self::MAX_SLICES)
137	            ->push([
138	                'total' => $slices->slice(self::MAX_SLICES)->sum('total'),
139	                'label' => 'Altro',
140	                'color' => $this->colorToRgb(Color::Gray),
141	            ]);
142	    }
143	
144	    /**
145	     * @param  array<int, string>  $color
146	     */
147	    private function colorToRgb(array $color): string
148	    {
149	        return "rgb({$color[500]})";
150	    }
151	}
