23	     * se la sessione contiene già un filtro esplicito (anche vuoto, salvato prima
24	     * che questi default esistessero), il default non scatta più. Qui forziamo
25	     * i valori pre-calcolati ogni volta che entrambi i campi risultano vuoti.
26	     */
27	    public function mount(): void
28	    {
29	        if (filled($this->filters['startDate'] ?? null) || filled($this->filters['endDate'] ?? null)) {
30	            return;
31	        }
32	
33	        $range = $this->getUserActivitiesDateRange();
34	
35	        $this->filters['startDate'] = $range->min;
36	        $this->filters['endDate'] = $range->max;
37	
38	        $this->getFiltersForm()->fill($this->filters);
39	
40	        if ($this->persistsFiltersInSession()) {
41	            session()->put($this->getFiltersSessionKey(), $this->filters);
42	        }
43	    }
