37	        $this->filters['endDate'] = $range->max;
38	
39	        $this->getFiltersForm()->fill($this->filters);
40	
41	        if ($this->persistsFiltersInSession()) {
42	            session()->put($this->getFiltersSessionKey(), $this->filters);
43	        }
44	    }
