3	namespace App\Filament\Pages;
4	
5	use App\Models\Activity;
6	use Carbon\Carbon;
7	use Filament\Forms\Components\Actions\Action;
8	use Filament\Forms\Components\DatePicker;
9	use Filament\Forms\Components\Select;
10	use Filament\Forms\Form;
11	use Filament\Forms\Set;
12	use Filament\Pages\Dashboard as BaseDashboard;
13	use Filament\Pages\Dashboard\Concerns\HasFiltersForm;
14	
15	/**
16	 * Dashboard con filtro per periodo, condiviso da tutti i widget.
17	 */
18	class Dashboard extends BaseDashboard
19	{
20	    use HasFiltersForm;
21	
22	    /**
23	     * Filament applica il default di un campo solo al primissimo fill "da zero":
24	     * se la sessione contiene già un filtro esplicito (anche vuoto, salvato prima
25	     * che questi default esistessero), il default non scatta più. Qui forziamo
26	     * i valori pre-calcolati ogni volta che entrambi i campi risultano vuoti.
27	     */
28	    public function mount(): void
29	    {
30	        if (filled($this->filters['startDate'] ?? null) || filled($this->filters['endDate'] ?? null)) {
31	            return;
32	        }
33	
34	        $range = $this->getUserActivitiesDateRange();
35	
36	        $this->filters['startDate'] = $range->min;
37	        $this->filters['endDate'] = $range->max;
38	
39	        $this->getFiltersForm()->fill($this->filters);
40	
41	        if ($this->persistsFiltersInSession()) {
42	            session()->put($this->getFiltersSessionKey(), $this->filters);
43	        }
44	    }
45	
46	    public function filtersForm(Form $form): Form
47	    {
48	        return $form
49	            ->schema([
50	                Select::make('preset')
51	                    ->label('Periodo rapido')
52	                    ->placeholder('Personalizzato')
53	                    ->options([
54	                        'all' => 'Tutte',
55	                        'current_week' => 'Settimana corrente',
56	                        'current_month' => 'Mese corrente',
57	                        'current_year' => 'Anno corrente',
58	                        'last_7_days' => 'Ultimi 7 giorni',
59	                        'last_30_days' => 'Ultimi 30 giorni',
60	                        'last_year' => 'Ultimo anno',
61	                    ])
62	                    ->live()
63	                    ->afterStateUpdated(function (?string $state, Set $set) {
64	                        if ($state === null) {
65	                            return;
66	                        }
67	
68	                        [$start, $end] = $this->getPresetRange($state);
69	
70	                        $set('startDate', $start);
71	                        $set('endDate', $end);
72	                    })
73	                    ->columnSpanFull(),
74	
75	                DatePicker::make('startDate')
76	                    ->label('Data inizio')
